def upgrade() -> None:
    """Upgrade schema."""
    # ### commands auto generated by Alembic - please adjust! ###
    op.add_column(
        "leave_ledger", sa.Column("annual_hours_before", sa.Integer(), nullable=True)
    )
    op.add_column(
        "leave_ledger", sa.Column("annual_hours_after", sa.Integer(), nullable=True)
    )
    # ### end Alembic commands ###

    # Rows written before these columns existed name both levels in the note
    # ("L1 -> L2"). The entitlement table is frozen here as it stood: L1 has
    # none, L2 to L4 have 80h.
    op.execute(
        """
        UPDATE leave_ledger
        SET annual_hours_before =
                CASE split_part(note, ' -> ', 1) WHEN 'L1' THEN 0 ELSE 80 END,
            annual_hours_after =
                CASE split_part(note, ' -> ', 2) WHEN 'L1' THEN 0 ELSE 80 END
        WHERE entry_type = 'level_change'
          AND split_part(note, ' -> ', 1) IN ('L1', 'L2', 'L3', 'L4')
          AND split_part(note, ' -> ', 2) IN ('L1', 'L2', 'L3', 'L4')
        """
    )
    op.create_check_constraint(
        "level_change_hours",
        "leave_ledger",
        "(entry_type = 'level_change')"
        " = (annual_hours_before IS NOT NULL AND annual_hours_after IS NOT NULL)",
    )


